import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ApiService } from '../../services/api.service';
import { ProfileResponse } from '../../models/models';

@Component({
  selector: 'app-profile',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './profile.component.html',
  styleUrl: './profile.component.css'
})
export class ProfileComponent implements OnInit {
  profile: ProfileResponse | null = null;
  loading = true;
  error: string | null = null;

  constructor(private apiService: ApiService) { }

  ngOnInit(): void {
    this.loadProfile();
  }

  loadProfile(): void {
    this.apiService.getProfile().subscribe({
      next: (data) => {
        this.profile = data;
        this.loading = false;
      },
      error: (err) => {
        console.error('Error loading profile:', err);
        this.error = 'Failed to load profile';
        this.loading = false;
      }
    });
  }
}
<div class="profile-container">
  <div *ngIf="loading" class="loading">Loading...</div>
  <div *ngIf="error" class="error">{{ error }}</div>
  <div *ngIf="profile && !loading" class="profile-content">
    <div class="profile-header">
      <h1>{{ profile.name }}</h1>
      <p class="title">{{ profile.title }}</p>
    </div>

    <div class="profile-bio">
      <p>{{ profile.bio }}</p>
    </div>

    <div class="profile-info">
      <div class="info-item">
        <strong>Email:</strong> <a [href]="'mailto:' + profile.email">{{ profile.email }}</a>
      </div>
    </div>

    <div class="skills-section">
      <h2>Skills</h2>
      <div class="skills-list">
        <span *ngFor="let skill of profile.skills" class="skill-tag">{{ skill }}</span>
      </div>
    </div>

    <div class="social-links">
      <h2>Connect</h2>
      <a [href]="profile.github" target="_blank" class="social-link">GitHub</a>
      <a [href]="profile.linkedin" target="_blank" class="social-link">LinkedIn</a>
    </div>
  </div>
</div>
